package router

import (
	"chain"

	ufmt "gno.land/p/nt/ufmt/v0"

	gnsmath "gno.land/p/gnoswap/gnsmath/v1"
	prbac "gno.land/p/gnoswap/rbac/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/halt/v1"

	pf "gno.land/r/gnoswap/protocol_fee"
	_ "gno.land/r/gnoswap/protocol_fee/v1"
)

// GetSwapFee returns the current router fee rate in basis points.
//
// Returns:
//   - fee: configured router fee in basis points
func (r *routerV1) GetSwapFee() uint64 {
	return r.store.GetSwapFee()
}

// SetSwapFee sets the protocol swap fee rate.
//
// Fee is deducted from swap output and sent to protocol fee contract.
// Only callable by admin or governance.
//
// Parameters:
//   - _: leading call discriminator; callers pass 0
//   - rlm: propagated current realm context; it must be current for the authorized storage write
//   - fee: new protocol fee rate in basis points, bounded to 0 through 1000
//
// Access:
//   - Requires: Admin or Governance role
//   - Halt check: Router and ProtocolFee must not be halted
//
// Events:
//   - SetSwapFee: Emits previous and new fee values
//
// Reverts if:
//   - Caller is not admin/governance
//   - Fee > 1000 bps (10%)
//   - Router or ProtocolFee is halted
func (r *routerV1) SetSwapFee(_ int, rlm realm, fee uint64) {
	access.AssertIsRlmCurrent(0, rlm)

	halt.AssertIsNotHaltedRouter()
	halt.AssertIsNotHaltedProtocolFee()

	previousRealm := rlm.Previous()
	caller := previousRealm.Address()
	access.AssertIsAdminOrGovernance(caller)

	// max swap fee is 1000 (bps)
	if fee > 1000 {
		panic(ufmt.Errorf(
			"%s: fee must be in range 0 to 1000 (10%). got %d",
			errInvalidSwapFee, fee,
		))
	}

	prevSwapFee := r.store.GetSwapFee()
	if err := r.store.SetSwapFee(0, rlm, fee); err != nil {
		panic(err)
	}

	chain.Emit(
		"SetSwapFee",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"newFee", utils.FormatUint(fee),
		"prevFee", utils.FormatUint(prevSwapFee),
	)
}

// handleSwapFee deducts the protocol fee from the swap amount and transfers it to the protocol fee contract.
func (r *routerV1) handleSwapFee(
	_ int,
	rlm realm,
	outputToken string,
	amount int64,
) int64 {
	currentTokenPath := outputToken

	swapFee := r.store.GetSwapFee()
	if swapFee <= 0 {
		r.settleProtocolFee(0, rlm, currentTokenPath, 0)
		return amount
	}

	feeAmountInt64 := calculateRouterFee(amount, swapFee)
	r.settleProtocolFee(0, rlm, currentTokenPath, feeAmountInt64)

	previousRealm := rlm.Previous()
	chain.Emit(
		"SwapRouteFee",
		"prevAddr", previousRealm.Address().String(),
		"prevRealm", previousRealm.PkgPath(),
		"tokenPath", currentTokenPath,
		"amount", utils.FormatInt(feeAmountInt64),
	)

	return gnsmath.SafeSubInt64(amount, feeAmountInt64)
}

// GetPendingProtocolFees returns pending protocol fee amounts keyed by token path.
//
// Returns:
//   - fees: token-path to pending amount map held by the router
func (r *routerV1) GetPendingProtocolFees() map[string]int64 {
	return r.store.GetPendingProtocolFees()
}

func (r *routerV1) addPendingProtocolFee(_ int, rlm realm, tokenPath string, amount int64) {
	if amount <= 0 {
		return
	}

	pendingAmount := gnsmath.SafeAddInt64(r.store.GetPendingProtocolFee(tokenPath), amount)
	if err := r.store.SetPendingProtocolFee(0, rlm, tokenPath, pendingAmount); err != nil {
		panic(err)
	}
}

// settleProtocolFee forwards amount, plus anything already pending for tokenPath, to
// the protocol fee realm. When collection is halted or the transfer fails, the amount
// is recorded as pending instead and settled by a later call for the same token, which
// every fee path makes even when the fee is zero.
//
// Only tokenPath is touched, so an unrelated token can never block settlement. The
// pending entry is written only when the fee cannot be forwarded, so the common path
// performs no store write at all.
func (r *routerV1) settleProtocolFee(_ int, rlm realm, tokenPath string, amount int64) {
	if halt.IsHaltedProtocolFee() {
		r.addPendingProtocolFee(0, rlm, tokenPath, amount)
		return
	}

	pendingAmount := r.store.GetPendingProtocolFee(tokenPath)
	totalAmount := gnsmath.SafeAddInt64(pendingAmount, amount)

	if totalAmount > 0 {
		protocolFeeAddr := access.MustGetAddress(prbac.ROLE_PROTOCOL_FEE.String())
		common.SafeGRC20Approve(0, rlm, tokenPath, protocolFeeAddr, totalAmount)

		// AddToProtocolFee only reports an error for a halted realm, which is handled
		// above. The branch keeps the amount pending should that ever change, and
		// withdraws the approval so no unspent allowance outlives the call.
		if err := pf.AddToProtocolFee(cross(rlm), tokenPath, totalAmount); err != nil {
			common.SafeGRC20Approve(0, rlm, tokenPath, protocolFeeAddr, 0)
			r.addPendingProtocolFee(0, rlm, tokenPath, amount)
			return
		}
	}

	if err := r.store.RemovePendingProtocolFee(0, rlm, tokenPath); err != nil {
		panic(err)
	}
}

func calculateRouterFee(amount int64, swapFee uint64) int64 {
	if swapFee <= 0 {
		return 0
	}

	feeAmount := u256.MulDiv(u256.NewUintFromInt64(amount), u256.NewUint(swapFee), u256.NewUint(10000))
	return gnsmath.SafeConvertToInt64(feeAmount)
}

// calculate amount to fetch from pool including router fee
// poolAmount = userAmount / (1 - feeRate)
// = userAmount * 10000 / (10000 - swapFeeBPS)
func calculateExactOutWithRouterFee(amount int64, swapFee uint64) int64 {
	if amount == 0 {
		return amount
	}

	if swapFee > 0 {
		// Use MulDiv to prevent overflow and maintain precision
		poolAmount := u256.MulDiv(
			u256.NewUintFromInt64(amount),
			u256.NewUint(10000),
			u256.NewUint(10000-swapFee),
		)

		return gnsmath.SafeConvertToInt64(poolAmount)
	}

	return amount
}

package router

import (
	"errors"
	"strconv"

	ufmt "gno.land/p/nt/ufmt/v0"
)

// ErrorMessages define all error message templates used throughout the router
const (
	// slippage validation
	errExactInAmountMismatch  = "consumed input does not match requested (requested=%d, consumed=%d)"
	errExactOutAmountExceeded = "received more than requested in requested=%d, actual=%d"

	// route validation
	errInvalidRouteLength = "route length(%d) must be 1~7"

	// quote validation
	errRoutesQuotesMismatch = "mismatch between routes(%d) and quotes(%d) length"
	errInvalidQuote         = "invalid quote(%s) at index(%d)"
	errInvalidQuoteValue    = "quote(%s) at index(%d) must be positive value"
	errQuoteExceedsMax      = "quote(%s) at index(%d) must be less than or equal to %d"
	errQuoteSumExceedsMax   = "quote sum exceeds 100 at index(%d)"
	errInvalidQuoteSum      = "quote sum(%d) must be 100"

	// swap type validation
	errExactInTooFewReceived = "ExactIn: too few received (min:%d, got:%d)"
	errExactOutTooMuchSpent  = "ExactOut: too much spent (max:%d, used:%d)"

	// route parsing validation
	errEmptyRoutes = "routes cannot be empty"
)

// SwapValidator provides validation methods for swap operations
type SwapValidator struct{}

// exactOutAmount checks if output amount meets specified requirements.
// For exact-out swaps, the output must be exactly the specified amount with tolerance up to swapCount units for rounding.
func (v *SwapValidator) exactOutAmount(resultAmount, specifiedAmount int64, swapCount int64) error {
	diff := int64(0)

	if resultAmount >= specifiedAmount {
		diff = resultAmount - specifiedAmount
	} else {
		diff = specifiedAmount - resultAmount
	}

	if diff > swapCount {
		return ufmt.Errorf(errExactOutAmountExceeded, specifiedAmount, resultAmount)
	}

	return nil
}

// exactInAmount checks that the swap consumed exactly the requested input amount.
func (v *SwapValidator) exactInAmount(resultAmount, specifiedAmount int64) error {
	if resultAmount != specifiedAmount {
		return ufmt.Errorf(errExactInAmountMismatch, specifiedAmount, resultAmount)
	}

	return nil
}

// slippage ensures swap amounts meet slippage requirements.
func (v *SwapValidator) slippage(swapType SwapType, amountIn, amountOut, limit int64) error {
	switch swapType {
	case ExactIn:
		if amountOut < limit {
			return ufmt.Errorf(errExactInTooFewReceived, limit, amountOut)
		}
	case ExactOut:
		if amountIn > limit {
			return ufmt.Errorf(errExactOutTooMuchSpent, limit, amountIn)
		}
	default:
		return errors.New(errInvalidSwapType)
	}
	return nil
}

// swapType ensures the swap type string is valid.
func (v *SwapValidator) swapType(swapTypeStr string) (SwapType, error) {
	swapType, err := trySwapTypeFromStr(swapTypeStr)
	if err != nil {
		return Unknown, errors.New(errInvalidSwapType)
	}
	return swapType, nil
}

// amount ensures the amount is properly formatted and positive.
func (v *SwapValidator) amount(amount int64) (int64, error) {
	if amount <= 0 {
		return 0, ufmt.Errorf(ErrInvalidPositiveAmount, amount)
	}
	return amount, nil
}

// RouteParser handles parsing and validation of routes and quotes
type RouteParser struct{}

// NewRouteParser creates a parser for comma-separated route and quote strings.
//
// Returns:
//   - parser: new RouteParser instance
func NewRouteParser() *RouteParser {
	return &RouteParser{}
}

// ParseRoutes splits route and quote strings and validates their pairing.
//
// Parameters:
//   - routes: comma-separated route paths
//   - quotes: comma-separated route allocation percentages
//
// Returns:
//   - routePaths: parsed route path strings
//   - quoteValues: parsed quote strings corresponding one-to-one with routePaths
//   - err: nil when routes, counts, and quote sum are valid; validation error otherwise
func (p *RouteParser) ParseRoutes(routes, quotes string) ([]string, []string, error) {
	// Check for empty routes
	if routes == "" || quotes == "" {
		return nil, nil, errors.New(errEmptyRoutes)
	}

	routesArr := splitSingleChar(routes, ',')
	quotesArr := splitSingleChar(quotes, ',')

	if err := p.ValidateRoutesAndQuotes(routesArr, quotesArr); err != nil {
		return nil, nil, err
	}

	return routesArr, quotesArr, nil
}

// ValidateRoutesAndQuotes checks route count, route/quote cardinality, and quote sum.
//
// Parameters:
//   - routes: parsed route path strings
//   - quotes: parsed quote percentage strings
//
// Returns:
//   - err: nil when one to seven routes match quote count and quotes sum to 100; validation error otherwise
func (p *RouteParser) ValidateRoutesAndQuotes(routes, quotes []string) error {
	rr := len(routes)
	qq := len(quotes)

	if rr < 1 || rr > 7 {
		return ufmt.Errorf(errInvalidRouteLength, rr)
	}

	if rr != qq {
		return ufmt.Errorf(errRoutesQuotesMismatch, rr, qq)
	}

	return p.ValidateQuoteSum(quotes)
}

// ValidateQuoteSum verifies that each quote is positive, at most 100, and totals 100.
//
// Parameters:
//   - quotes: route allocation percentage strings
//
// Returns:
//   - err: nil when all quotes parse and total 100; invalid value or sum error otherwise
func (p *RouteParser) ValidateQuoteSum(quotes []string) error {
	const (
		maxQuote int8 = 100
		minQuote int8 = 0
	)

	var sum int8

	for i, quote := range quotes {
		qt, err := strconv.ParseInt(quote, 10, 8)
		if err != nil {
			return ufmt.Errorf(errInvalidQuote, quote, i)
		}
		intQuote := int8(qt)

		// Quote must be positive (> 0) as each route needs a non-zero allocation.
		// A quote of 0 would mean no swap through that route, which is invalid.
		if intQuote <= minQuote { // minQuote = 0, so this rejects quote = 0
			return ufmt.Errorf(errInvalidQuoteValue, quote, i)
		}

		if intQuote > maxQuote {
			return ufmt.Errorf(errQuoteExceedsMax, quote, i, maxQuote)
		}

		if sum > maxQuote-intQuote {
			return ufmt.Errorf(errQuoteSumExceedsMax, i)
		}

		sum += intQuote
	}

	if sum != maxQuote {
		return ufmt.Errorf(errInvalidQuoteSum, sum)
	}

	return nil
}

// finalizeSwap handles post-swap operations and validations.
func (r *routerV1) finalizeSwap(
	_ int,
	rlm realm,
	inputToken, outputToken string,
	resultAmountIn, resultAmountOut int64,
	swapType SwapType,
	tokenAmountLimit int64,
	amountSpecified int64,
	swapCount int64,
	isSetSqrtPriceLimitX96 bool,
) (int64, int64) {
	validator := &SwapValidator{}

	// Handle swap fee
	resultAmountOutWithoutFee := r.handleSwapFee(0, rlm, outputToken, resultAmountOut)

	// Validate the exact-out target when no caller price limit is set. A
	// nonzero single-hop limit permits partial output, so only the max-input
	// slippage check below remains applicable.
	if swapType == ExactOut && !isSetSqrtPriceLimitX96 {
		if err := validator.exactOutAmount(resultAmountOutWithoutFee, amountSpecified, swapCount); err != nil {
			panic(addDetailToError(errSlippage, err.Error()))
		}
	}

	// Validate exact in amount if applicable
	// If sqrtPriceLimitX96 is set, partial consumption up to the price limit is intended
	if swapType == ExactIn && !isSetSqrtPriceLimitX96 {
		if err := validator.exactInAmount(resultAmountIn, amountSpecified); err != nil {
			panic(addDetailToError(errInsufficientLiquidity, err.Error()))
		}
	}

	if err := validator.slippage(swapType, resultAmountIn, resultAmountOutWithoutFee, tokenAmountLimit); err != nil {
		panic(addDetailToError(errSlippage, err.Error()))
	}

	return resultAmountIn, resultAmountOutWithoutFee
}

// validateRoutesAndQuotes is a convenience function that parses and validates routes in one call.
func validateRoutesAndQuotes(routes, quotes string) ([]string, []string, error) {
	return NewRouteParser().ParseRoutes(routes, quotes)
}

package router

import (
	"errors"
	"strings"

	"gno.land/p/gnoswap/gnsmath/v1"
	"gno.land/p/gnoswap/utils/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/common"
)

// QuoteConstraints defines the valid range for swap quote percentages
const (
	MaxQuotePercentage     = 100
	MinQuotePercentage     = 0
	PERCENTAGE_DENOMINATOR = int64(100)
)

// ErrorMessages for DrySwapRoute operations
const (
	ErrUnknownSwapType       = "unknown swapType(%s)"
	ErrInvalidPositiveAmount = "invalid amount(%s), must be positive"
	ErrInvalidQuoteRange     = "quote(%d) must be %d~%d"
)

// SwapProcessor handles the execution of swap operations
type SwapProcessor struct {
	router *routerV1
}

// ProcessSingleSwap simulates one pool hop without executing transfers.
//
// Parameters:
//   - route: single pool path formatted as TOKEN0:TOKEN1:FEE
//   - amountSpecified: signed input or output amount for the hop
//
// Returns:
//   - amountIn: input amount the pool would receive
//   - amountOut: output amount the pool would send
//   - err: always nil when the dry pool call returns; malformed paths or pool failures panic in the underlying helpers
func (p *SwapProcessor) ProcessSingleSwap(route string, amountSpecified int64) (amountIn, amountOut int64, err error) {
	input, output, fee := getDataForSinglePath(route)
	singleParams := SingleSwapParams{
		tokenIn:         input,
		tokenOut:        output,
		fee:             fee,
		amountSpecified: amountSpecified,
	}

	amountIn, amountOut = p.router.singleDrySwap(&singleParams)
	return amountIn, amountOut, nil
}

// ProcessMultiSwap simulates a multi-hop route in the requested direction.
//
// Parameters:
//   - swapType: ExactIn for forward execution or ExactOut for backward quoting
//   - route: multi-hop path with POOL_SEPARATOR between hops
//   - numHops: number of pools in route
//   - amountSpecified: signed input or output amount for the route
//
// Returns:
//   - amountIn: input amount the route would consume
//   - amountOut: output amount the route would produce
//   - err: nil on successful simulation; invalid swap-type error or downstream dry-swap validation error otherwise (pool query failures panic)
func (p *SwapProcessor) ProcessMultiSwap(
	swapType SwapType,
	route string,
	numHops int,
	amountSpecified int64,
) (int64, int64, error) {
	pathIndex := getPathIndex(swapType, numHops)

	input, output, fee := getDataForMultiPath(route, pathIndex)
	singleParams := SingleSwapParams{
		tokenIn:         input,
		tokenOut:        output,
		fee:             fee,
		amountSpecified: amountSpecified,
	}

	switch swapType {
	case ExactIn:
		return p.router.multiDrySwap(singleParams, numHops, route)
	case ExactOut:
		return p.router.multiDrySwapNegative(singleParams, numHops, route)
	default:
		return 0, 0, ufmt.Errorf(ErrUnknownSwapType, swapType)
	}
}

// ValidateSwapResults checks simulated amounts against exactness and slippage constraints.
//
// Parameters:
//   - swapType: ExactIn or ExactOut validation direction
//   - resultAmountIn: simulated aggregate input amount
//   - resultAmountOut: simulated aggregate output amount after router fee
//   - amountSpecified: caller's exact input or output target
//   - amountLimit: minimum output or maximum input slippage bound
//   - swapCount: number of pool hops used for exact-output tolerance
//
// Returns:
//   - amountIn: resultAmountIn when validation reaches the return path
//   - amountOut: resultAmountOut when validation reaches the return path
//   - err: nil when liquidity, exactness, and slippage checks pass; relevant validation error otherwise
func (p *SwapProcessor) ValidateSwapResults(
	swapType SwapType,
	resultAmountIn, resultAmountOut int64,
	amountSpecified, amountLimit int64,
	swapCount int64,
) (amountIn, amountOut int64, err error) {
	if resultAmountIn == 0 || resultAmountOut == 0 {
		return 0, 0, errors.New(errInsufficientLiquidity)
	}

	validator := &SwapValidator{}

	if swapType == ExactOut {
		absSpecified := gnsmath.SafeAbsInt64(amountSpecified)

		if err := validator.exactOutAmount(resultAmountOut, absSpecified, swapCount); err != nil {
			return resultAmountIn, resultAmountOut, err
		}
	}

	if swapType == ExactIn {
		if err := validator.exactInAmount(resultAmountIn, amountSpecified); err != nil {
			return resultAmountIn, resultAmountOut, err
		}
	}

	if err := validator.slippage(swapType, resultAmountIn, resultAmountOut, amountLimit); err != nil {
		return resultAmountIn, resultAmountOut, err
	}

	return resultAmountIn, resultAmountOut, nil
}

// AddSwapResults adds one route's amounts to accumulated totals using overflow-safe arithmetic.
//
// Parameters:
//   - resultAmountIn: accumulated input before this route
//   - resultAmountOut: accumulated output before this route
//   - amountIn: current route input amount
//   - amountOut: current route output amount
//
// Returns:
//   - newAmountIn: accumulated input after adding amountIn
//   - newAmountOut: accumulated output after adding amountOut
//   - err: always nil; overflow is raised by safe arithmetic rather than returned
func (p *SwapProcessor) AddSwapResults(
	resultAmountIn, resultAmountOut, amountIn, amountOut int64,
) (int64, int64, error) {
	newAmountIn := gnsmath.SafeAddInt64(resultAmountIn, amountIn)
	newAmountOut := gnsmath.SafeAddInt64(resultAmountOut, amountOut)

	return newAmountIn, newAmountOut, nil
}

// DrySwapRoute simulates a token swap route without executing transfers or changing state.
//
// Parameters:
//   - inputToken: input token contract path
//   - outputToken: output token contract path
//   - specifiedAmount: exact input amount for EXACT_IN or exact output amount for EXACT_OUT
//   - swapTypeStr: EXACT_IN or EXACT_OUT
//   - strRouteArr: comma-separated route paths, with at most seven route entries
//   - quoteArr: comma-separated route allocation percentages summing to 100
//   - tokenAmountLimit: minimum output for EXACT_IN or maximum input for EXACT_OUT
//
// Returns:
//   - amountIn: simulated input amount encoded as a decimal string
//   - amountOut: simulated net output amount encoded as a decimal string
//   - err: nil on success; validation, liquidity, parsing, or slippage error otherwise
func (r *routerV1) DrySwapRoute(
	inputToken, outputToken string,
	specifiedAmount string,
	swapTypeStr string,
	strRouteArr, quoteArr string,
	tokenAmountLimit string,
) (amountIn, amountOut string, err error) {
	defer func() {
		if r := recover(); r != nil {
			amountIn = "0"
			amountOut = "0"
			if recoveredErr, ok := r.(error); ok {
				err = recoveredErr
			} else {
				err = ufmt.Errorf("%v", r)
			}
		}
	}()

	inputAmount, outputAmount, err := r.drySwapRoute(
		inputToken,
		outputToken,
		utils.SafeParseInt64(specifiedAmount),
		swapTypeStr,
		strRouteArr,
		quoteArr,
		utils.SafeParseInt64(tokenAmountLimit),
	)
	return utils.FormatInt(inputAmount), utils.FormatInt(outputAmount), err
}

// drySwapRoute is the internal dry-run swap simulation that returns errors
// instead of panicking on validation or liquidity failures.
func (r *routerV1) drySwapRoute(
	inputToken, outputToken string,
	specifiedAmount int64,
	swapTypeStr string,
	strRouteArr, quoteArr string,
	tokenAmountLimit int64,
) (int64, int64, error) {
	if err := common.ValidateRegistered(inputToken, outputToken); err != nil {
		return 0, 0, err
	}

	assertIsValidRoutePaths(strRouteArr, inputToken, outputToken)
	assertIsExistsPools(strRouteArr)

	// initialize components
	validator := &SwapValidator{}
	processor := &SwapProcessor{router: r}

	// validate and parse inputs
	swapType, err := validator.swapType(swapTypeStr)
	if err != nil {
		return 0, 0, makeErrorWithDetails(errInvalidSwapType, err.Error())
	}

	amountSpecified, err := validator.amount(specifiedAmount)
	if err != nil {
		return 0, 0, makeErrorWithDetails(errInvalidInput, err.Error())
	}

	routes, quotes, err := NewRouteParser().ParseRoutes(strRouteArr, quoteArr)
	if err != nil {
		return 0, 0, makeErrorWithDetails(errInvalidRoutesAndQuotes, err.Error())
	}

	swapFee := r.store.GetSwapFee()

	// Store original amount for validation (before router fee adjustment)
	originalAmountSpecified := amountSpecified

	// adjust amount sign for exact out swaps
	if swapType == ExactOut {
		absSpecified := gnsmath.SafeAbsInt64(amountSpecified)
		amountSpecifiedWithRouterFee := calculateExactOutWithRouterFee(absSpecified, swapFee)
		amountSpecified = -amountSpecifiedWithRouterFee
	}

	// initialize accumulators for swap results
	resultAmountIn, resultAmountOut := int64(0), int64(0)
	remainRequestAmount := amountSpecified
	swapCount := int64(0)

	// Process each route
	for i, route := range routes {
		toSwapAmount := int64(0)

		// if it's the last route, use the remaining amount
		isLastRoute := i == len(routes)-1
		if !isLastRoute {
			// calculate the amount to swap for this route
			swapAmount, err := calculateSwapAmountByQuote(amountSpecified, quotes[i])
			if err != nil {
				return 0, 0, err
			}

			// update the remaining amount
			resultRemainRequestAmount := gnsmath.SafeSubInt64(remainRequestAmount, swapAmount)

			remainRequestAmount = resultRemainRequestAmount
			toSwapAmount = swapAmount
		} else {
			toSwapAmount = remainRequestAmount
		}

		// determine the number of hops and validate
		numHops := strings.Count(route, POOL_SEPARATOR) + 1
		assertHopsInRange(numHops)

		// accumulate total swap count for validation
		swapCount += int64(numHops)

		// execute the appropriate swap type
		var amountIn, amountOut int64
		if numHops == 1 {
			amountIn, amountOut, err = processor.ProcessSingleSwap(route, toSwapAmount)
		} else {
			amountIn, amountOut, err = processor.ProcessMultiSwap(swapType, route, numHops, toSwapAmount)
		}

		if err != nil {
			return 0, 0, err
		}

		if amountIn == 0 || amountOut == 0 {
			return 0, 0, errors.New(errInsufficientLiquidity)
		}

		// update accumulated results
		resultAmountIn, resultAmountOut, err = processor.AddSwapResults(resultAmountIn, resultAmountOut, amountIn, amountOut)
		if err != nil {
			return 0, 0, err
		}
	}

	// simulate deduct router fee
	feeAmountInt64 := calculateRouterFee(resultAmountOut, swapFee)

	resultAmountOut = gnsmath.SafeSubInt64(resultAmountOut, feeAmountInt64)

	return processor.ValidateSwapResults(swapType, resultAmountIn, resultAmountOut, originalAmountSpecified, tokenAmountLimit, swapCount)
}

// getPathIndex returns the path index based on swap type and number of hops.
func getPathIndex(swapType SwapType, numHops int) int {
	switch swapType {
	case ExactIn:
		// first data for exact input swaps
		return 0
	case ExactOut:
		// last data for exact output swaps
		return numHops - 1
	default:
		panic("should not happen")
	}
}

package router

import (
	"errors"

	prbac "gno.land/p/gnoswap/rbac/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	ufmt "gno.land/p/nt/ufmt/v0"

	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/common"
	"gno.land/r/gnoswap/halt/v1"
)

// SwapCallback implements the pool's SwapCallback interface.
// The pool invokes it after sending output tokens; the router then transfers the
// positive input delta to the pool.
//
// Parameters:
//   - _: leading callback discriminator; callers pass 0
//   - rlm: propagated current realm context; must remain the current crossing frame
//   - token0Path: token-0 contract path in canonical pool order
//   - token1Path: token-1 contract path in canonical pool order
//   - amount0Delta: signed token-0 delta; positive means the pool is owed this amount
//   - amount1Delta: signed token-1 delta; positive means the pool is owed this amount
//   - payer: address whose balance supplies the positive input delta
//
// Returns:
//   - err: nil after the owed input transfer; an error for spoofed realm, invalid liquidity delta, or failed payment
//
// Positive deltas are tokens the pool must receive; negative deltas are tokens
// the pool has sent to the recipient.
func (r *routerV1) SwapCallback(
	_ int,
	rlm realm,
	token0Path, token1Path string,
	amount0Delta, amount1Delta int64,
	payer address,
) error {
	if !rlm.IsCurrent() {
		return errors.New(errSpoofedRealm)
	}

	if amount0Delta <= 0 && amount1Delta <= 0 {
		return makeErrorWithDetails(
			errInsufficientLiquidity,
			"swap entirely within 0-liquidity region",
		)
	}

	halt.AssertIsNotHaltedRouter()

	caller := rlm.Previous().Address()
	assertIsRouterImplementation(caller)

	var tokenToPay string
	var amountToPay int64

	// amount0Delta > 0 means pool wants token0
	// amount1Delta > 0 means pool wants token1
	if amount0Delta > 0 {
		amountToPay = amount0Delta
		tokenToPay = token0Path
	} else {
		amountToPay = amount1Delta
		tokenToPay = token1Path
	}

	// Transfer tokens from router to pool
	// The router should already have the tokens from the user
	r.transferToPool(0, rlm, tokenToPay, u256.NewUintFromInt64(amountToPay), payer)

	return nil
}

// transferToPool transfers tokens from router to pool
func (r *routerV1) transferToPool(_ int, rlm realm, token string, amount *u256.Uint, payer address) {
	balance := common.BalanceOf(token, payer)

	if u256.NewUintFromInt64(balance).Lt(amount) {
		panic(makeErrorWithDetails(
			errInsufficientBalance,
			ufmt.Sprintf("token=%s, required=%d, available=%d, payer=%s", token, amount.Int64(), balance, payer.String()),
		))
	}

	poolAddr := access.MustGetAddress(prbac.ROLE_POOL.String())
	routerAddr := access.MustGetAddress(prbac.ROLE_ROUTER.String())

	if payer == routerAddr {
		common.SafeGRC20Transfer(0, rlm, token, poolAddr, amount.Int64())
	} else {
		common.SafeGRC20TransferFrom(0, rlm, token, payer, poolAddr, amount.Int64())
	}
}

package router

import (
	"gno.land/r/gnoswap/access/v1"
	"gno.land/r/gnoswap/router"

	i256 "gno.land/p/gnoswap/int256/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"
	"gno.land/p/gnoswap/utils/v1"

	pl "gno.land/r/gnoswap/pool"
)

const (
	MIN_SQRT_RATIO_PLUS_ONE  string = "4295128740"
	MAX_SQRT_RATIO_MINUS_ONE string = "1461446703485210103287273052203988822378723970341"
)

// swapInner executes the core swap logic by interacting with the pool contract.
// Returns poolRecv (tokens received by pool) and poolOut (tokens sent by pool).
func (r *routerV1) swapInner(
	_ int,
	rlm realm,
	amountSpecified int64,
	recipient address,
	sqrtPriceLimitX96 *u256.Uint,
	data SwapCallbackData,
) (int64, int64) {
	assertIsRouterProxyRealm(0, rlm)

	token0Path, token1Path := data.tokenIn, data.tokenOut
	zeroForOne := data.tokenIn < data.tokenOut

	if !zeroForOne {
		token0Path, token1Path = token1Path, token0Path
	}

	sqrtPriceLimitStr := calculateSqrtPriceLimitToStr(zeroForOne, sqrtPriceLimitX96)

	amount0Str, amount1Str := pl.Swap(
		cross(rlm),
		token0Path,
		token1Path,
		data.fee,
		recipient,
		zeroForOne,
		utils.FormatInt(amountSpecified),
		sqrtPriceLimitStr,
		func(cur realm, amount0Delta, amount1Delta int64, _ *pl.CallbackMarker) error {
			// assert is pool to prevent unauthorized callback
			caller := cur.Previous().Address()
			access.AssertIsPool(caller)

			return router.SwapCallback(cross(cur), token0Path, token1Path, amount0Delta, amount1Delta, data.payer)
		},
	)

	amount0 := i256.MustFromDecimal(amount0Str)
	amount1 := i256.MustFromDecimal(amount1Str)

	poolOut, poolRecv := i256MinMax(amount0, amount1)
	if poolRecv.IsOverflow() || poolOut.IsOverflow() {
		panic("overflow in swapInner")
	}

	return poolRecv.Int64(), poolOut.Int64()
}

// swapDryInner performs a dry-run of a swap operation without executing it.
func (r *routerV1) swapDryInner(
	amountSpecified int64,
	sqrtPriceLimitX96 *u256.Uint,
	data SwapCallbackData,
) (int64, int64) {
	token0Path, token1Path := data.tokenIn, data.tokenOut
	zeroForOne := data.tokenIn < data.tokenOut

	if !zeroForOne {
		token0Path, token1Path = token1Path, token0Path
	}

	sqrtPriceLimitStr := calculateSqrtPriceLimitToStr(zeroForOne, sqrtPriceLimitX96)

	// check possible
	amount0Str, amount1Str, err := pl.DrySwap(
		token0Path,
		token1Path,
		data.fee,
		zeroForOne,
		utils.FormatInt(amountSpecified),
		sqrtPriceLimitStr,
	)
	if err != nil {
		panic(err)
	}

	amount0 := i256.MustFromDecimal(amount0Str)
	amount1 := i256.MustFromDecimal(amount1Str)
	if amount0.Sign() <= 0 && amount1.Sign() <= 0 {
		panic(makeErrorWithDetails(
			errInsufficientLiquidity,
			"swap entirely within 0-liquidity region",
		))
	}

	poolOut, poolRecv := i256MinMax(amount0, amount1)
	if poolRecv.IsOverflow() || poolOut.IsOverflow() {
		panic("overflow in swapDryInner")
	}

	return poolRecv.Int64(), poolOut.Int64()
}

// calculateSqrtPriceLimitToStr returns the price-limit string for a swap operation.
// A non-zero caller limit is formatted as-is; a zero limit uses the global
// TickMath boundary for the swap direction.
func calculateSqrtPriceLimitToStr(zeroForOne bool, sqrtPriceLimitX96 *u256.Uint) string {
	if !sqrtPriceLimitX96.IsZero() {
		return sqrtPriceLimitX96.ToString()
	}

	if zeroForOne {
		return MIN_SQRT_RATIO_PLUS_ONE
	}
	return MAX_SQRT_RATIO_MINUS_ONE
}

package router

import (
	prbac "gno.land/p/gnoswap/rbac/v1"
	u256 "gno.land/p/gnoswap/uint256/v1"

	"gno.land/r/gnoswap/access/v1"
)

// multiSwap performs a multi-hop exact-input swap in forward order.
func (r *routerV1) multiSwap(_ int, rlm realm, sp SwapParams, numPools int, swapPath string) (int64, int64) {
	payer := rlm.Previous().Address()
	routerAddr := access.MustGetAddress(prbac.ROLE_ROUTER.String())
	firstAmountIn := int64(0)

	for currentPoolIndex := 0; ; currentPoolIndex++ {
		callbackData := newSwapCallbackData(sp, payer)
		amountIn, amountOut := r.swapInner(
			0,
			rlm,
			sp.amountSpecified,
			sp.recipient,
			u256.Zero(),
			callbackData,
		)

		// every hop of a forward multi-hop swap is exact-in
		assertHopFullyConsumed(currentPoolIndex, sp.amountSpecified, amountIn)

		if currentPoolIndex == 0 {
			firstAmountIn = amountIn
		}

		nextPoolIndex := currentPoolIndex + 1
		if nextPoolIndex >= numPools {
			return firstAmountIn, amountOut
		}

		payer = routerAddr
		nextInput, nextOutput, nextFee := getDataForMultiPath(swapPath, nextPoolIndex)
		sp.tokenIn = nextInput
		sp.tokenOut = nextOutput
		sp.fee = nextFee
		sp.amountSpecified = amountOut
	}
}

// multiSwapNegative performs a multi-hop exact-output swap. It first quotes
// every hop backward, then executes the collected swaps forward.
func (r *routerV1) multiSwapNegative(_ int, rlm realm, sp SwapParams, numPools int, swapPath string) (int64, int64) {
	swapInfo := r.collectBackwardDrySwapInfo(sp.SingleSwapParams, numPools, swapPath)
	return r.executeCollectedSwaps(0, rlm, swapInfo, sp.recipient)
}

// multiDrySwap simulates a multi-hop exact-input swap in forward order.
func (r *routerV1) multiDrySwap(sp SingleSwapParams, numPools int, swapPath string) (int64, int64, error) {
	firstAmountIn := int64(0)

	for currentPoolIndex := 0; ; currentPoolIndex++ {
		amountIn, amountOut := r.swapDryInner(
			sp.amountSpecified,
			u256.Zero(),
			newDrySwapCallbackData(sp),
		)

		// mirror the real-swap full-consumption guard so dry runs predict reverts
		err := validateHopFullyConsumed(currentPoolIndex, sp.amountSpecified, amountIn)
		if err != nil {
			return 0, 0, err
		}

		if currentPoolIndex == 0 {
			firstAmountIn = amountIn
		}

		nextPoolIndex := currentPoolIndex + 1
		if nextPoolIndex >= numPools {
			return firstAmountIn, amountOut, nil
		}

		nextInput, nextOutput, nextFee := getDataForMultiPath(swapPath, nextPoolIndex)
		sp.tokenIn = nextInput
		sp.tokenOut = nextOutput
		sp.fee = nextFee
		sp.amountSpecified = amountOut
	}
}

// multiDrySwapNegative simulates a multi-hop exact-output swap.
// It first quotes every hop backward, then simulates the collected swaps forward.
func (r *routerV1) multiDrySwapNegative(sp SingleSwapParams, numPools int, swapPath string) (int64, int64, error) {
	swapInfo := r.collectBackwardDrySwapInfo(sp, numPools, swapPath)
	return r.executeCollectedDrySwaps(swapInfo)
}

// collectBackwardDrySwapInfo quotes an exact-output route backward before real execution.
func (r *routerV1) collectBackwardDrySwapInfo(sp SingleSwapParams, numPools int, swapPath string) []SingleSwapParams {
	swapInfo := make([]SingleSwapParams, 0, numPools)

	for currentPoolIndex := numPools - 1; currentPoolIndex >= 0; currentPoolIndex-- {
		amountIn, _ := r.singleDrySwap(&sp)
		swapInfo = append(swapInfo, sp)

		if currentPoolIndex == 0 {
			break
		}

		nextPoolIndex := currentPoolIndex - 1
		nextInput, nextOutput, nextFee := getDataForMultiPath(swapPath, nextPoolIndex)
		sp.tokenIn = nextInput
		sp.tokenOut = nextOutput
		sp.fee = nextFee
		sp.amountSpecified = -amountIn
	}

	return swapInfo
}

// executeCollectedSwaps executes the backward-quoted exact-output swaps in forward order.
func (r *routerV1) executeCollectedSwaps(_ int, rlm realm, swapInfo []SingleSwapParams, recipient address) (int64, int64) {
	payer := rlm.Previous().Address()
	routerAddr := access.MustGetAddress(prbac.ROLE_ROUTER.String())
	firstAmountIn := int64(0)

	for currentPoolIndex := len(swapInfo) - 1; currentPoolIndex >= 0; currentPoolIndex-- {
		amountIn, amountOut := r.swapInner(
			0,
			rlm,
			swapInfo[currentPoolIndex].amountSpecified,
			recipient,
			u256.Zero(),
			newSwapCallbackData(swapInfo[currentPoolIndex], payer),
		)

		// hops re-specified from the previous hop's actual output run as exact-in
		// (positive amountSpecified) and must consume that amount entirely
		if spec := swapInfo[currentPoolIndex].amountSpecified; spec > 0 {
			assertHopFullyConsumed(currentPoolIndex, spec, amountIn)
		}

		if currentPoolIndex == len(swapInfo)-1 {
			firstAmountIn = amountIn
		}

		if currentPoolIndex == 0 {
			return firstAmountIn, amountOut
		}

		nextPoolIndex := currentPoolIndex - 1
		swapInfo[nextPoolIndex].amountSpecified = amountOut
		payer = routerAddr
	}

	return firstAmountIn, 0
}

func (r *routerV1) executeCollectedDrySwaps(swapInfo []SingleSwapParams) (int64, int64, error) {
	firstAmountIn := int64(0)

	for currentPoolIndex := len(swapInfo) - 1; currentPoolIndex >= 0; currentPoolIndex-- {
		amountIn, amountOut := r.swapDryInner(
			swapInfo[currentPoolIndex].amountSpecified,
			u256.Zero(),
			newDrySwapCallbackData(swapInfo[currentPoolIndex]),
		)

		// mirror the real-swap full-consumption guard so dry runs predict reverts
		if spec := swapInfo[currentPoolIndex].amountSpecified; spec > 0 {
			err := validateHopFullyConsumed(currentPoolIndex, spec, amountIn)
			if err != nil {
				return 0, 0, err
			}
		}

		if currentPoolIndex == len(swapInfo)-1 {
			firstAmountIn = amountIn
		}

		if currentPoolIndex == 0 {
			return firstAmountIn, amountOut, nil
		}

		nextPoolIndex := currentPoolIndex - 1
		swapInfo[nextPoolIndex].amountSpecified = amountOut
	}

	return firstAmountIn, 0, nil
}

